ALTER TABLE public.bar_stock_purchases ADD COLUMN invoice_files jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.bar_stock_purchases ADD CONSTRAINT bar_purchase_invoice_files_array CHECK(jsonb_typeof(invoice_files)='array');
CREATE POLICY "Bar managers read purchase invoices" ON storage.objects FOR SELECT TO authenticated USING (bucket_id='bar-purchase-invoices' AND (public.is_club_admin_or_permitted(auth.uid(),((storage.foldername(name))[1])::uuid,'bar') OR public.is_club_admin_or_permitted(auth.uid(),((storage.foldername(name))[1])::uuid,'finance') OR public.is_club_chairman(auth.uid(),((storage.foldername(name))[1])::uuid)));
CREATE POLICY "Bar managers upload purchase invoices" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='bar-purchase-invoices' AND public.is_club_admin_or_permitted(auth.uid(),((storage.foldername(name))[1])::uuid,'bar') AND public.chairman_financial_write_allowed(((storage.foldername(name))[1])::uuid));
CREATE POLICY "Bar managers remove unlinked invoice uploads" ON storage.objects FOR DELETE TO authenticated USING (bucket_id='bar-purchase-invoices' AND public.is_club_admin_or_permitted(auth.uid(),((storage.foldername(name))[1])::uuid,'bar') AND public.chairman_financial_write_allowed(((storage.foldername(name))[1])::uuid) AND NOT EXISTS (SELECT 1 FROM public.bar_stock_purchases p WHERE p.club_id=((storage.foldername(name))[1])::uuid AND p.invoice_files @> jsonb_build_array(jsonb_build_object('path',name))));